  if (!instance || instance.PingStatus !== "Online") {
    throw new Error(`EC2 ${instanceId} \u672A\u901A\u8FC7 Systems Manager \u5728\u7EBF\uFF0C\u5F53\u524D\u4E0D\u80FD\u8BFB\u53D6 Docker \u8FD0\u884C\u6001`);
  }
